 6	final class KahnTopologicalSorter {
 7	    List<Integer> sort(DirectedGraph graph) {
 8	        int[] indegree = graph.buildIndegreeTable();
 9	        Deque<Integer> readyVertices = collectZeroIndegreeVertices(indegree);
10	        List<Integer> order = new ArrayList<>(graph.vertexCount());
11	
12	        while (!readyVertices.isEmpty()) {
13	            int vertex = readyVertices.removeFirst();
14	            order.add(vertex);
15	            for (int next : graph.neighborsOf(vertex)) {
16	                indegree[next]--;
17	                if (indegree[next] == 0) {
18	                    readyVertices.addLast(next);
19	                }
20	            }
21	        }
22	
23	        validateAcyclic(graph, order);
24	        return order;
25	    }
26	
27	    private Deque<Integer> collectZeroIndegreeVertices(int[] indegree) {
28	        Deque<Integer> readyVertices = new ArrayDeque<>();
29	        for (int vertex = 0; vertex < indegree.length; vertex++) {
30	            if (indegree[vertex] == 0) {
31	                readyVertices.addLast(vertex);
32	            }
33	        }
34	        return readyVertices;
35	    }
36	
37	    private void validateAcyclic(DirectedGraph graph, List<Integer> order) {
38	        if (order.size() != graph.vertexCount()) {
39	            throw new IllegalStateException("Topological sort requires a directed acyclic graph.");
40	        }
41	    }
42	}

